const cut = new Date(Date.now()-3*864e5).toISOString().slice(0,10);
const rows = items.map(i=>i.json).filter(r => r.LinkSent && r.LinkSent <= cut && (r.PaidStatus||'').toLowerCase() !== 'paid');
if (!rows.length) return [];
return [{ json: { text: '💬 Gentle chase today:\n' + rows.map(r => `• ${r.Customer} ₹${r.Amount} → https://wa.me/${String(r.Phone).replace(/\D/g,'')}?text=${encodeURIComponent('Namaste '+r.Customer+' ji! Gentle reminder about the pending payment of ₹'+r.Amount+'. The link is still active — thank you! 🙏')}`).join('\n') } }];

const d = new Date();
const dom = d.getDate(), ym = d.toISOString().slice(0,7);
const rows = items.map(i=>i.json).filter(r => Number(r.DayOfMonth) === dom && r.LastPaidMonth !== ym && r.Phone);
if (!rows.length) return [];
return [{ json: { text: '💰 Scheme instalments due today:\n' + rows.map(r => `• ${r.Name} ₹${r.Monthly} → https://wa.me/${String(r.Phone).replace(/\D/g,'')}?text=${encodeURIComponent('Namaste '+r.Name+' ji! Your gold-savings instalment of ₹'+r.Monthly+' is due today. Reply here or visit us — thank you! ✨ '+($env.BRAND_NAME||''))}`).join('\n') } }];
